(() => {
  'use strict';
  const P=window.Portal,e=P.e,root='https://www.kraftringen.se/';
  const products={consumer:['Rörligt månadspris','Rörligt kvartspris','Kraftringen Opti'],business:['Rörligt månadspris','Rörligt kvartspris','Individuell indexportfölj','Kraftringen Stabil','Kraftringen Direkt','Poolportfölj – offensiv','Poolportfölj – trygg']};
  const items=[
    ['consumer','Rörligt månadspris','Ett elpris per kWh som fastställs i efterhand för månaden och följer marknaden.','Hushåll som vill följa marknaden utan att planera förbrukningen kvart för kvart.',['Enkel modell att följa månad för månad','Minskad elanvändning sänker kostnaden'],'Passar när enkelhet är viktigare än att styra användningen till vissa kvartar.','Priset kan stiga. Att flytta användning mellan kvartar sänker inte det egna månadspriset.','privat/el/vara-elavtal/rorligt-manadspris/'],
    ['consumer','Rörligt kvartspris','Energipriset följer spotmarknaden varje kvart och den egna elanvändningen.','Aktiva hushåll med flyttbar förbrukning, exempelvis laddning eller uppvärmning.',['Möjlighet att påverka kostnaden genom när elen används','Tydlig koppling mellan marknadspris och användning'],'Utgå från vad kunden faktiskt kan flytta till billigare kvartar.','Dyra kvartar kan höja kostnaden. Besparing är ingen garanti.','privat/el/vara-elavtal/rorligt-kvartspris/'],
    ['consumer','Kraftringen Opti','Kraftringen jämför utfallet av månadspris och kvartspris för kundens faktiska förbrukning och väljer det billigare alternativet.','Hushåll som vill kunna påverka förbrukningen men slippa välja mellan de två prismodellerna.',['Automatisk jämförelse inför fakturan','Möjlighet att dra nytta av flyttbar förbrukning'],'Två avtalsalternativ jämförs åt kunden – kunden behöver inte välja rätt modell i förväg.','Det är inte en garanti för marknadens lägsta pris eller ett fast pristak. Jämför även avgifterna.','privat/el/vara-elavtal/kraftringen-opti/'],
    ['business','Rörligt månadspris','Företagets elpris sätts månadsvis i efterskott. Marknadspris, rörliga kostnader och avtalade avgifter påverkar utfallet.','Företag som kan hantera prisvariationer och vill ha en enkel inköpsmodell.',['Följer marknaden','Ingen daglig styrning krävs för prismodellen'],'Börja med företagets budgetutrymme för svängande elkostnader.','Priset kan gå både upp och ned. Kontrollera företagets egna villkor.','foretag/el/vara-elavtal/rorligt-elpris/'],
    ['business','Rörligt kvartspris','Energikostnaden följer spotpriset och företagets användning i varje kvart.','Företag som kan planera eller styra delar av sin elanvändning.',['Påverkbar kostnad genom tidpunkt','Underlag för aktiv energistyrning'],'Kartlägg flyttbar last innan du beskriver möjliga besparingar.','Företagets exakta prisformel och produktblad behöver kompletteras.','', 'Befintligt utbildningsunderlag · företagsspecifika villkor saknas'],
    ['business','Individuell indexportfölj','En egen plan med successiva, regelstyrda inköp och prissäkringar för överenskomna månadsvolymer.','Elintensiva företag som behöver en inköpsplan anpassad till sin förbrukningsprofil.',['Inköp sprids över tid','Planen utgår från kundens volymer'],'Koppla upplägget till verksamhetens månadsprofil och önskade risknivå.','Webbkällan beskriver portföljförvaltning generellt. Exakt mandat, prisformel och horisont måste avtalas.','foretag/el/vara-elavtal/portfoljforvaltning/', 'Utbildningsunderlag + generell webbförklaring'],
    ['business','Kraftringen Stabil','Systempris och elområdesskillnad säkras vid ett tillfälle för överenskommen volym och period enligt projektets bekräftade utbildningsunderlag.','Företag som vill säkra dessa priskomponenter för en planerad förbrukningsprofil.',['Tydlighet för den säkrade delen','Förbrukningsprofilen vägs in i upplägget'],'Förklara exakt vilka komponenter och volymer som säkras.','Osäkrad el, dygnsprofil och andra kostnader ligger separat. Hela fakturan är inte fast.','', 'Bekräftat utbildningsunderlag · aktuellt produktblad behövs'],
    ['business','Kraftringen Direkt','Produkten finns i orderkatalogen. En verifierad produktbeskrivning saknas ännu.','Kompletteras av produktansvarig.',['Kundvärden kompletteras när produktbladet finns'],'Säljargument kompletteras efter bekräftad produktdefinition.','Anta inte prisformel, risknivå eller avtalsvillkor utifrån namnet.','', 'Underlag saknas'],
    ['business','Poolportfölj – offensiv','Gemensam inköpspool med successiv prissäkring och en aktivt förvaltad del enligt utbildningsunderlaget.','Företag som vill kombinera gemensam förvaltning med aktiva marknadsbeslut.',['Delad inköpsstrategi','Inköp sprids över tid'],'Beskriv möjligheten att agera på marknaden tillsammans med risken för sämre utfall.','Aktiv förvaltning kan ge både bättre och sämre resultat. Offertens mandat styr.','foretag/el/vara-elavtal/poolportfolj/', 'Utbildningsunderlag + generell webbförklaring'],
    ['business','Poolportfölj – trygg','Gemensam inköpspool med regelstyrda prissäkringar som byggs upp successivt enligt utbildningsunderlaget.','Företag som prioriterar spridda inköp och mindre beroende av en enda inköpstidpunkt.',['Gemensam förvaltning','Minskad koncentration av inköpsrisk över tid'],'Förklara hur successiva inköp kan jämna ut prisutvecklingen.','Ingen garanti om lägst pris eller helt fast slutkostnad. Offertens volymbas styr.','foretag/el/vara-elavtal/poolportfolj/', 'Utbildningsunderlag + generell webbförklaring']
  ].map(([category,name,description,fit,values,pitch,caution,source,basis])=>({category,name,description,fit,values,pitch,caution,source,basis:basis||'Webbunderlag kontrollerat 27 oktober 2026'}));
  // Explicit fictional examples only. Never import public historical spot prices as an offer.
  const priceLists=[
    {id:'standard-demo-v1',name:'Standard · exempelpriser',version:'1',date:'2026-10-27',partners:null,discount:0},
    {id:'face2face-demo-v1',name:'Face2face · exempelprislista',version:'1',date:'2026-10-27',partners:['vast'],discount:1},
    {id:'savera-demo-v1',name:'Savera · exempelprislista',version:'1',date:'2026-10-27',partners:['syd'],discount:1}
  ];
  const choices=new Map();let category=new URLSearchParams(location.search).get('factSegment')==='business'?'business':'consumer';
  const currentPartner=()=>P.role==='internal'?P.selectedPartnerId:P.partner;
  const lists=(partner=currentPartner())=>priceLists.filter(l=>!l.partners||l.partners.includes(partner));
  function selected(partner=currentPartner()){const id=choices.get(partner);return lists(partner).some(l=>l.id===id)?id:'standard-demo-v1';}
  function select(id,partner=currentPartner()){if(!lists(partner).some(l=>l.id===id))return false;choices.set(partner,id);return true;}
  const getProduct=(cat,name)=>items.find(p=>p.category===cat&&p.name===name);
  function snapshot(id,cat,name,partner=P.partner){
    const list=lists(partner).find(l=>l.id===id),product=getProduct(cat,name);if(!list||!product)return null;
    const quoted=cat==='business'&&!['Rörligt månadspris','Rörligt kvartspris'].includes(name);
    return {listId:list.id,listName:list.name,version:list.version,date:list.date,category:cat,product:name,demo:true,currency:'SEK',vat:cat==='consumer'?'inkl. moms':'exkl. moms',monthly:quoted?null:(name==='Kraftringen Opti'?119:cat==='consumer'?59:79)-list.discount*20,markup:quoted?null:(cat==='consumer'?5:6)-list.discount,energy:quoted?'Enligt individuell prisformel/offert':'Marknadsbaserad energidel och rörliga kostnader tillkommer',status:quoted?'Prisunderlag saknas':'Fiktivt räkneexempel'};
  }
  const number=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n);
  function priceHTML(s){if(!s)return '<p class="pc-missing">Prisreferens saknas.</p>';return `<div class="pc-price"><span class="eyebrow">${e(s.status)} · ${e(s.vat)}</span>${s.monthly===null?'<strong>Prisunderlag saknas</strong><p>Individuell offert behöver kompletteras.</p>':`<div class="pc-price-pair"><div><strong>${number(s.monthly)} <small>kr/mån</small></strong><span>Månadsavgift per anläggning</span></div><div><strong>${number(s.markup)} <small>öre/kWh</small></strong><span>Fast påslag</span></div></div>`}<p>${e(s.energy)}. Elnät och energiskatt ingår inte. Detta är inte ett totalt elpris.</p></div>`;}
  function listOptions(id,partner=currentPartner()){return lists(partner).map(l=>`<option value="${e(l.id)}"${l.id===id?' selected':''}>${e(l.name)}</option>`).join('');}
  function orderFields(draft){return `<label class="ow-field">Prislista *<select name="priceListId">${listOptions(draft.priceListId,P.partner)}</select></label>`;}
  function orderPrice(draft){return `<section class="pc-order-price" aria-label="Orderns prisreferens"><strong>Vald prislista · endast exempelpriser</strong>${priceHTML(snapshot(draft.priceListId,draft.category,draft.product))}<small>Prislistans version och komponenter sparas med ordern. Inget bindande erbjudande skapas.</small></section>`;}
  function savedPrice(row){const s=row.priceSnapshot;return `<section class="pc-order-price"><h3>Sparad prisreferens</h3>${s?`<p>${e(s.listName)} · version ${e(s.version)} · ${e(s.date)}${s.demo?' · Fiktiva exempelpriser':''}</p>${priceHTML(s)}`:'<p>Äldre order · ingen prislista eller prisreferens sparad. Inga priser har lagts till i efterhand.</p>'}</section>`;}
  const lessonNames={'Rörligt kvartspris':'Kvartspris','Kraftringen Opti':'Opti','Individuell indexportfölj':'Individuell portfölj','Poolportfölj – offensiv':'Poolportfölj Offensiv','Poolportfölj – trygg':'Poolportfölj Trygg'};
  function factBody(p){const name=p.category==='business'&&p.name==='Rörligt månadspris'?'Rörligt pris':lessonNames[p.name]||p.name;return P.productFacts?.rows.find(r=>r[0]===p.category&&r[1]===name)?.[2]||'';}
  function materialLinks(p){
    const name=lessonNames[p.name]||p.name,lesson=P.productFacts?.lessons[name];
    const terms=root+(p.category==='consumer'?'privat':'foretag')+'/el/vara-elavtal/avtalsvillkor/';
    return `<div class="pc-material"><strong>Fördjupningsmaterial</strong>${lesson?`<a href="${e(P.productFacts.lessonHref(lesson[0],p.category))}">Se film och produktlektion →</a><a href="utbildning-preview/produktspecifikationer.pdf#page=${lesson[1]}" target="_blank" rel="noopener">Produktspecifikation · sida ${lesson[1]} ↗</a>`:'<span>Produktspecifikation och film behöver kompletteras.</span>'}<a href="${terms}" target="_blank" rel="noopener">Avtalsvillkor hos Kraftringen ↗</a></div>`;
  }
  function render(){
    const id=selected(),list=lists().find(l=>l.id===id);const canOrder=P.role==='partner'&&['sales','field'].includes(P.getPartner()?.type)&&!P.demoMode;
    return `<div class="ow-page pc-page"><header class="pc-heading"><div><span class="eyebrow">PRODUKTGUIDE / ELHANDEL</span><h1>Produkter</h1><p>Hitta rätt avtal för kunden – och gå direkt till ordern.</p></div><button class="btn btn-secondary" data-go="academy">Utbildning →</button></header><section class="card pc-toolbar"><label>Prislista<select id="pc-price-list">${listOptions(id)}</select></label><div><strong>${e(list.name)}</strong><p>Version ${e(list.version)} · exempel daterat ${e(list.date)}</p></div></section><p class="pc-notice" role="status"><strong>Alla belopp är fiktiva exempelpriser.</strong> De visar hur prislistvalet fungerar och är inte Kraftringens aktuella erbjudanden. Fastställda standard- och partnerprislistor behöver kompletteras. Spotpris och total kundkostnad visas inte som fasta priser.</p><div class="pc-categories" role="group" aria-label="Produktkategori">${[['consumer','Konsumenter'],['business','Företag']].map(([id,label])=>`<button class="btn ${category===id?'btn-primary':'btn-secondary'}" data-pc-category="${id}" aria-pressed="${category===id}">${label} <span>${products[id].length}</span></button>`).join('')}</div><div class="pc-grid">${items.filter(p=>p.category===category).map(p=>`<article class="card pc-product"><div><span class="eyebrow">${category==='consumer'?'KONSUMENTER':'FÖRETAG'}</span><h2>${e(p.name)}</h2><p>${e(p.description)}</p></div><div class="pc-fit"><h3>Passar bäst för</h3><p>${e(p.fit)}</p></div><h3>Kundvärden</h3><ul>${p.values.map(v=>`<li>${e(v)}</li>`).join('')}</ul><details><summary>Säljargument & att tänka på</summary><p><strong>I kundsamtalet:</strong> ${e(p.pitch)}</p><p><strong>Att tänka på:</strong> ${e(p.caution)}</p>${factBody(p)?`<p><strong>Avtalsfakta från befintligt underlag:</strong> ${e(factBody(p))}</p>`:''}<p class="muted">Målgrupp och säljargument är redaktionella förslag utifrån underlaget.</p><p>${e(p.basis)}</p>${p.source?`<a href="${root+p.source}" target="_blank" rel="noopener">Kraftringens produktbeskrivning ↗</a>`:''}${p.basis.includes('utbildningsunderlag')||p.basis.includes('Utbildningsunderlag')?'<p><a href="utbildning-preview/produktspecifikationer.pdf" target="_blank" rel="noopener">Befintlig produktspecifikation ↗</a></p>':''}</details>${materialLinks(p)}${priceHTML(snapshot(id,p.category,p.name,currentPartner()))}${canOrder?`<button class="btn btn-primary pc-create" data-pc-order="${e(p.name)}" data-pc-segment="${p.category}" aria-label="Skapa order för ${e(p.name)}">Skapa order →</button>`:'<p class="muted">Öppna en säljpartners förhandsvisning för att skapa en exempelorder.</p>'}</article>`).join('')}</div><details class="card pc-archive"><summary>Fler avtalsformer i utbildningsmaterialet</summary><p>Fastpris och Vintersäkrat finns kvar som fördjupning. De ingår inte i den aktuella orderkatalogen.</p>${['Fastpris','Vintersäkrat'].map(name=>`<h3>${name}</h3><p>${e(factBody({name,category:'consumer'}))}</p>${materialLinks({name,category:'consumer'})}`).join('')}</details><p class="muted">Guiden innehåller samma 3 konsumentprodukter och 7 företagsprodukter som orderformuläret. Produktnamn kan skilja sig från webbplatsens. <a href="${root}privat/el/vara-elpriser/" target="_blank" rel="noopener">Se aktuella publika konsumentpriser ↗</a></p></div>`;
  }
  function bind(){document.querySelector('#pc-price-list')?.addEventListener('change',ev=>{select(ev.target.value);P.render();document.querySelector('#pc-price-list')?.focus();});document.querySelectorAll('[data-pc-category]').forEach(b=>b.onclick=()=>{category=b.dataset.pcCategory;P.render();document.querySelector('[data-pc-category][aria-pressed="true"]')?.focus();});document.querySelectorAll('[data-pc-order]').forEach(b=>b.onclick=()=>{const cat=b.dataset.pcSegment,name=b.dataset.pcOrder;if(!getProduct(cat,name))return;P.orderWorkspace?.startProductOrder({category:cat,product:name,priceListId:selected()});});}
  P.productCatalog={products,items,lists,selected,select,snapshot,priceHTML,orderFields,orderPrice,savedPrice};
  P.register('products',{render,bind});
  // Old teaching links keep working; property-specific choices retain their original scope.
  const oldFacts=P.routes['product-facts'];
  const property=()=>P.role==='partner'&&P.getPartner()?.type==='property';
  P.register('product-facts',{render:()=>property()?oldFacts.render():render(),bind:()=>property()?oldFacts.bind?.():bind()});
})();
